-- ============================================================
-- IMPORT CATÁLOGO v3 — Cole no Supabase SQL Editor
-- ============================================================
DO $$
DECLARE v_tenant_id UUID;
BEGIN
  SELECT id INTO v_tenant_id FROM public.tenants LIMIT 1;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Nenhum tenant encontrado. Crie o tenant antes de importar.';
  END IF;

  ON CONFLICT (tenant_id, variant_id) DO UPDATE SET
    technical_attributes = EXCLUDED.technical_attributes,
    brand_slug = EXCLUDED.brand_slug,
    product_slug = EXCLUDED.product_slug,
    updated_at = NOW();

  RAISE NOTICE 'Importadas % variantes.', 2450;
END $$;
